const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pick=(value,lang)=>Array.isArray(value)?value[lang==='en'?1:0]:value;
const n=(x,y,label,sub='',w=145)=>({x,y,label,sub,w});
