function body(config,lang){
 if(config.kind==='hierarchy')return `<rect x="35" y="20" width="675" height="215" rx="16" fill="#eaf1ec" stroke="#b8ccbe"/><text x="60" y="55">AI · ${lang==='en'?'Artificial Intelligence':'인공지능'}</text><rect x="185" y="75" width="495" height="135" rx="13" fill="#dce9df" stroke="#aec4b4"/><text x="210" y="106">ML · ${lang==='en'?'Machine Learning':'머신러닝'}</text><rect x="360" y="128" width="290" height="58" rx="10" fill="#52745e"/><text x="505" y="162" text-anchor="middle" fill="white">${lang==='en'?'Deep Learning':'딥러닝'}</text>`;
 if(config.kind==='network'){
  const layers=[[65,[85,155]],[270,[50,120,190]],[480,[85,155]],[670,[120]]];let out='';
  for(let i=0;i<layers.length-1;i++)for(const y of layers[i][1])for(const yy of layers[i+1][1])out+=`<line x1="${layers[i][0]}" y1="${y}" x2="${layers[i+1][0]}" y2="${yy}" stroke="#c2d3c8"/>`;
  layers.forEach(([x,ys],i)=>{ys.forEach(y=>out+=`<circle cx="${x}" cy="${y}" r="17" fill="${i===3?'#587963':'#e3eee6'}" stroke="#91b29b"/>`);out+=`<text x="${x}" y="235" text-anchor="middle">${pick([['입력','Input'],['은닉층 1','Hidden 1'],['은닉층 2','Hidden 2'],['출력','Output']][i],lang)}</text>`;});return out;
 }
 if(config.kind==='matrix'){
  let out=`<text x="315" y="28" text-anchor="middle">${lang==='en'?'Predicted positive':'양성 예측'}</text><text x="560" y="28" text-anchor="middle">${lang==='en'?'Predicted negative':'음성 예측'}</text>`;
  [[65,'TP',['올바른 탐지','Correct detection'],'#e2eee5'],[155,'FP',['오탐','False alarm'],'#f5eee3']].forEach(([y,key,label,fill],i)=>{out+=`<text x="95" y="${y+40}" text-anchor="middle">${lang==='en'?(i?'Actual negative':'Actual positive'):(i?'실제 음성':'실제 양성')}</text>`;out+=`<rect x="195" y="${y}" width="230" height="75" rx="8" fill="${fill}"/><text x="310" y="${y+30}" text-anchor="middle">${key}</text><text class="diagram-sub" x="310" y="${y+55}" text-anchor="middle">${pick(label,lang)}</text>`;const label2=i?['올바른 제외','Correct rejection']:['미탐','Missed detection'];out+=`<rect x="440" y="${y}" width="230" height="75" rx="8" fill="${i?'#e2eee5':'#f5eee3'}"/><text x="555" y="${y+30}" text-anchor="middle">${i?'TN':'FN'}</text><text class="diagram-sub" x="555" y="${y+55}" text-anchor="middle">${pick(label2,lang)}</text>`;});return out;
 }
 let out='';
 for(const [from,to]of config.edges){const a=config.nodes[from],b=config.nodes[to];const dx=b.x+b.w/2-a.x-a.w/2,dy=b.y-a.y;const horizontal=Math.abs(dy)<80||Math.abs(dx)>250;const x1=horizontal?(dx>=0?a.x+a.w:a.x):a.x+a.w/2,y1=horizontal?a.y+30:(dy>=0?a.y+60:a.y),x2=horizontal?(dx>=0?b.x:b.x+b.w):b.x+b.w/2,y2=horizontal?b.y+30:(dy>=0?b.y:b.y+60);out+=`<path d="M ${x1} ${y1} C ${(x1+x2)/2} ${y1}, ${(x1+x2)/2} ${y2}, ${x2} ${y2}" fill="none" stroke="#9bb5a3" stroke-width="1.6" marker-end="url(#arrow)"/>`;}
 if(config.loop)out+='<path d="M 630 143 V 195 H 94 V 146" fill="none" stroke="#9bb5a3" stroke-width="1.5" stroke-dasharray="5 4" marker-end="url(#arrow)"/>';
 for(const node of config.nodes){const label=pick(node.label,lang),sub=pick(node.sub,lang);out+=`<rect x="${node.x}" y="${node.y}" width="${node.w}" height="60" rx="10" fill="#edf4ef" stroke="#c5d7cb"/><text x="${node.x+node.w/2}" y="${node.y+(sub?26:35)}" text-anchor="middle">${esc(label)}</text>${sub?`<text class="diagram-sub" x="${node.x+node.w/2}" y="${node.y+46}" text-anchor="middle">${esc(sub)}</text>`:''}`;}
 return out;
}
export function diagram(slug,lang){const c=configs[slug];if(!c)return '';const title=pick(c.title,lang),caption=pick(c.caption,lang),height=c.height||260;
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 ${height}" role="img" aria-labelledby="diagram-title diagram-desc"><title id="diagram-title">${esc(title)}</title><desc id="diagram-desc">${esc(caption)}</desc><style>text{font:14px system-ui,sans-serif;fill:#496852}.diagram-sub{font-size:11px;fill:#71877a}text[fill="white"]{fill:white}</style><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#9bb5a3"/></marker></defs>${body(c,lang)}</svg>`;
 return `<figure class="concept-diagram"><div class="diagram-heading"><strong>${esc(title)}</strong><a download="${slug}-${lang}.svg" href="data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}">SVG ↓</a></div><div class="diagram-scroll">${svg}</div><figcaption>${esc(caption)}<span>${lang==='en'?'Explanatory diagram created for whateveriwant · not a source figure':'whateveriwant 자체 제작 설명 도식 · 원문 이미지 아님'}</span></figcaption></figure>`;
}

